    },
    "output_key": "entities",
    "description": "Matches full court names including '(BFG)' suffix as a single entity. Updated to capture 'Bundesfinanzgericht' followed by optional genitive endings and the '(BFG)' suffix as one unit, preventing split matches.",
    "content": "\\b(?:Verwaltungsgerichtshof(?:es|s)?|Verfassungsgerichtshof(?:es|s)?|Landesgericht(?:es|s)\\s+[A-Z][a-z]+|Landesgerichts\\s+[A-Z])\\b"
  },
  {
    "name": "GmbH Company Names",
    "format": "regex",
    "priority": 17,
    "output_template": {
      "text": "$1",
      "start": "$start",
      "end": "$end",
      "type": "organisation"
    },
    "output_key": "entities",
    "description": "Matches company names ending in 'GmbH' with any alphanumeric prefix, including multiple words, hyphens, and '&' symbols, ensuring the full name is captured.",
    "content": "(?<!Firma\\s)(?<!Fa\\.\\s)\\b([A-Z][A-Za-z\\u00e4\\u00f6\\u00fc\\u00df\\-\\d\\s&]+(?:\\s+[A-Z][A-Za-z\\u00e4\\u00f6\\u00fc\\u00df\\-\\d\\s&]+)*\\s+GmbH)\\b"
  }
]

